// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { ChartPanel } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/ChartPanel)

figma.connect(ChartPanel, FIGMA_NODE_URL, {
  props: {
    label: figma.string('label'),
    unit: figma.string('unit'),
    padded: figma.boolean('padded'),
    border: figma.enum('border', { 'spotlight': 'spotlight', 'none': 'none', '1px': '1px' }),
  },
  example: ({ label, unit, padded, border }) => (
    <ChartPanel unit={unit} padded={padded} border={border}>{label}</ChartPanel>
  ),
});
